// CosmicWebCalculator.cs (#2021, Cosmic Web epic #2020)
//
// A 3D point set of "galaxies" in a periodic box, generated by a clustering model and drawn as a
// log-density point splat through an orbit camera. Generators: the hierarchical clustering model of
// Soneira & Peebles (AJ 83, 845, 1978; Engine/CosmicWeb/SoneiraPeebles.cs, #2021) and the Zel'dovich
// approximation (A&A 5, 84, 1970; Engine/CosmicWeb/Zeldovich.cs, #2022).
//
// Render (FF's own, CPU): the box is scaled to the unit cube centred on the origin and seen through
// the Math Plane 3D orbit camera (MathPlane3DCamera, z up, 45 degree vertical field of view). Each
// point adds a weight, 1 - DepthFade * t (t = 0 at the front of the box, 1 at the back), to every
// pixel within PointSize of its projection, and the same weight times its depth t to a depth sum. Both
// are fixed-point integers summed with atomic adds, so the frame is the same whatever the thread count
// or order. Tone map (empty pixels take the theme's interior colour), with a = log(1 + v) / log(1 + max):
//   Depth (default): hue = the theme at the pixel's mean depth, brightness = a^(1/gamma). This is the
//     log-density display with gamma of the fractal flame algorithm (Draves; FF's FlameRenderer), with
//     depth in place of the flame's colour coordinate.
//   Density: the theme at a, as the strange attractors are drawn.
//
// The points are cached per generator settings (a one-entry static cache shared by the live view,
// batch and poster export), so camera moves only re-splat. The Zel'dovich linear field and its
// displacement are cached apart from the growth factor D, so changing only D re-displaces the particles
// without running the FFTs again.
//
// #2023 — an optional D(r) measurement of the points (CosmicWebCalculator.Dimension.cs): a status-bar
// readout and an inset plot drawn into the frame.

using System;
using System.Threading;
using System.Threading.Tasks;

using FracturingFog.CosmicWeb;
using FracturingFog.Interefaces;
using FracturingFog.Models;
using FracturingFog.Rendering.Lighting;

namespace FracturingFog;

public sealed partial class CosmicWebCalculator : IFractalCalculator, IStereoEyeCamera, IDepthAovSource
{
    public int Width { get; private set; }
    public int Height { get; private set; }
    public uint[] ColorBuffer { get; private set; } = Array.Empty<uint>();
    /// <summary>Splat weight per pixel, fixed point (<see cref="WeightOne"/> = one full-weight point).</summary>
    public long[] DensityBuffer { get; private set; } = Array.Empty<long>();
    /// <summary>Per pixel: sum of weight x depth (fixed point, depth in units of 1/<see cref="DepthOne"/>).</summary>
    public long[] DepthSumBuffer { get; private set; } = Array.Empty<long>();

    public double CenterX { get; set; }
    public double CenterY { get; set; }
    public double Zoom { get; set; } = 1.0;
    public int MaxIterations { get; set; } = 256;
    public QualityPreset Quality { get; set; } = QualityPreset.Standard;
    public IColorMap ColorMap { get; set; } = new HsvPalette();
    public bool SupportsZoomPan => true;
    public FractalParameters FractalParameters { get; set; } = new();

    /// <summary>True-stereo eye offset along the camera's right axis (unit-cube units); 0 = mono.</summary>
    public double StereoEyeOffset { get; set; }
    /// <summary>Per-pixel ray distance to the nearest galaxy splatted there (unit-cube units;
    /// <see cref="ScreenSpacePost.DepthMiss"/> where none), published only when a pass wants it.</summary>
    public float[]? DepthBuffer { get; private set; }
    public bool DepthRequested { get; set; }

    /// <summary>Status-bar text: points, clumps, the cap and the model's analytic D.</summary>
    public string? LastPrecisionLabel { get; private set; }
    /// <summary>The points of the last frame.</summary>
    public CosmicWebPoints? LastPoints { get; private set; }

    /// <summary>Fixed-point unit of one full-weight point in <see cref="DensityBuffer"/>.</summary>
    public const long WeightOne = 256;
    /// <summary>Largest splat radius in pixels.</summary>
    public const double MaxPointSize = 8.0;
    /// <summary>Fixed-point unit of depth t = 1 in <see cref="DepthSumBuffer"/>.</summary>
    public const long DepthOne = 4096;

    private static readonly object s_cacheLock = new();
    private static SoneiraPeeblesSettings? s_cacheKey;
    private static CosmicWebPoints? s_cachePoints;
    private static readonly object s_zCacheLock = new();
    private static ZeldovichFieldSettings? s_zFieldKey;
    private static ZeldovichField? s_zField;
    private static (ZeldovichFieldSettings Field, double Growth, double Box)? s_zPointsKey;
    private static CosmicWebPoints? s_zPoints;

    public CosmicWebCalculator(int width, int height) => Resize(width, height);

    public void Resize(int width, int height)
    {
        Width = width;
        Height = height;
        ColorBuffer = new uint[width * height];
        DensityBuffer = new long[width * height];
        DepthSumBuffer = new long[width * height];
    }

    /// <summary>The generator settings of <paramref name="p"/>, sanitised.</summary>
    public static SoneiraPeeblesSettings SettingsOf(FractalParameters p) => SoneiraPeebles.Sanitise(new SoneiraPeeblesSettings(
        p.CosmicWebSeed, p.CosmicWebBoxSize, p.CosmicWebClumps, p.CosmicWebPlacement, p.CosmicWebEta,
        p.CosmicWebLambda, p.CosmicWebFirstRatio, p.CosmicWebTopSize, p.CosmicWebLevelMode, p.CosmicWebLevels,
        p.CosmicWebPointCap));

    /// <summary>The points for <paramref name="p"/>, from the cache when the settings are unchanged.</summary>
    public static CosmicWebPoints PointsFor(FractalParameters p, CancellationToken ct = default)
    {
        if (p.CosmicWebGenerator == CosmicWebGenerator.Zeldovich) return ZeldovichPointsFor(p, ct);
        if (p.CosmicWebGenerator == CosmicWebGenerator.Voronoi) return VoronoiPointsFor(p, ct);   // #2025
        var key = SettingsOf(p);
        lock (s_cacheLock)
        {
            if (s_cachePoints != null && key.Equals(s_cacheKey)) return s_cachePoints;
        }
        var pts = SoneiraPeebles.Generate(key, ct);
        if (ct.IsCancellationRequested) return pts;
        lock (s_cacheLock) { s_cacheKey = key; s_cachePoints = pts; }
        return pts;
    }

    /// <summary>#2022 — the Zel'dovich field settings of <paramref name="p"/>, sanitised.</summary>
    public static ZeldovichFieldSettings ZeldovichSettingsOf(FractalParameters p) => Zeldovich.Sanitise(new ZeldovichFieldSettings(
        p.CosmicWebSeed, p.CosmicWebGrid, p.CosmicWebSpectralIndex, p.CosmicWebSmoothing));

    /// <summary>#2022 — the linear field and displacement for <paramref name="p"/>, from the cache when unchanged.</summary>
    public static ZeldovichField ZeldovichFieldFor(FractalParameters p, CancellationToken ct = default)
    {
        var key = ZeldovichSettingsOf(p);
        lock (s_zCacheLock)
        {
            if (s_zField != null && key.Equals(s_zFieldKey)) return s_zField;
        }
        var f = Zeldovich.Build(key, ct);
        lock (s_zCacheLock) { s_zFieldKey = key; s_zField = f; }
        return f;
    }

    private static CosmicWebPoints ZeldovichPointsFor(FractalParameters p, CancellationToken ct)
    {
        var fieldKey = ZeldovichSettingsOf(p);
        double box = SoneiraPeebles.Sanitise(SettingsOf(p)).BoxSize;
        var key = (fieldKey, p.CosmicWebGrowth, box);
        lock (s_zCacheLock)
        {
            if (s_zPoints != null && key.Equals(s_zPointsKey)) return s_zPoints;
        }
        var f = ZeldovichFieldFor(p, ct);
        var pts = Zeldovich.Displace(f, p.CosmicWebGrowth, box, ct);
        lock (s_zCacheLock) { s_zPointsKey = key; s_zPoints = pts; }
        return pts;
    }

    /// <summary>#2025 — the Voronoi model settings of <paramref name="p"/>, sanitised.</summary>
    public static VoronoiSettings VoronoiSettingsOf(FractalParameters p) => VoronoiElement.Sanitise(new VoronoiSettings(
        p.CosmicWebSeed, p.CosmicWebBoxSize, p.CosmicWebVoronoiNuclei, p.CosmicWebVoronoiPoints,
        p.CosmicWebVoronoiField, p.CosmicWebVoronoiWalls, p.CosmicWebVoronoiFilaments, p.CosmicWebVoronoiClusters,
        p.CosmicWebVoronoiThickness));

    private static readonly object s_vorLock = new();
    private static VoronoiSettings? s_vorKey;
    private static CosmicWebPoints? s_vorPoints;

    private static CosmicWebPoints VoronoiPointsFor(FractalParameters p, CancellationToken ct)
    {
        var key = VoronoiSettingsOf(p);
        lock (s_vorLock)
            if (s_vorPoints != null && key.Equals(s_vorKey)) return s_vorPoints;
        var pts = VoronoiElement.Generate(key, ct);
        if (ct.IsCancellationRequested) return pts;
        lock (s_vorLock) { s_vorKey = key; s_vorPoints = pts; }
        return pts;
    }

    /// <summary>The camera for <paramref name="p"/> (box scaled to the unit cube about the origin).</summary>
    public static MathPlane3DCamera CameraFor(FractalParameters p, double zoom, int w, int h)
        => MathPlane3DCamera.For(p.CosmicWebCameraDistance, p.CosmicWebCameraTheta, p.CosmicWebCameraPhi,
                                 (0.0, 0.0, 0.0), zoom, w, h);

    public void Calculate(CancellationToken ct = default)
    {
        var p = FractalParameters;
        var pts = PointsFor(p, ct);
        if (ct.IsCancellationRequested) return;
        LastPoints = pts;
        int w = Width, h = Height;
        DepthBuffer = null;
        Array.Clear(DensityBuffer);
        Array.Clear(DepthSumBuffer);
        var cam = CameraFor(p, Zoom, w, h);
        if (StereoEyeOffset != 0)
        {
            double o = StereoEyeOffset;
            cam = cam with { Eye = (cam.Eye.X + cam.Right.X * o, cam.Eye.Y + cam.Right.Y * o, cam.Eye.Z + cam.Right.Z * o) };
        }
        var fx = p.Lighting;
        if (DepthRequested) fx.OverlayDepth = true;
        string volumeNote = "";
        if (p.CosmicWebRender == CosmicWebRender.Volume)
        {
            // #2024 — raymarched CIC density volume (CosmicWebCalculator.Volume.cs).
            if (!RenderVolume(p, pts, cam, ScreenSpacePost.WantsDepthOutput(in fx), ct, out volumeNote)) return;
        }
        else
        {
            int[]? nearest = null;
            if (ScreenSpacePost.WantsDepthOutput(in fx)) { nearest = new int[w * h]; Array.Fill(nearest, int.MaxValue); }
            Splat(pts, cam, p.CosmicWebPointSize, p.CosmicWebDepthFade, DensityBuffer, w, h, ct, DepthSumBuffer, nearest);
            if (ct.IsCancellationRequested) return;
            if (nearest != null)
            {
                var d = new float[w * h];
                for (int i = 0; i < d.Length; i++)
                    d[i] = nearest[i] == int.MaxValue ? ScreenSpacePost.DepthMiss : BitConverter.Int32BitsToSingle(nearest[i]);
                DepthBuffer = d;
            }
            ToneMap(p.CosmicWebColour, p.CosmicWebGamma);
        }
        if (p.CosmicWebGenerator == CosmicWebGenerator.Zeldovich)
        {
            var z = ZeldovichSettingsOf(p);
            LastPrecisionLabel = $"Zel'dovich: {z.Grid}^3 = {pts.Count:N0} particles, P(k) ~ k^{z.Index:0.##}, smoothing {z.Smoothing:0.##} cells, D = {p.CosmicWebGrowth:0.###} (rms linear density contrast)" + volumeNote;
            MeasureDimension(p, pts, null, ct);   // #2023
            return;
        }
        if (p.CosmicWebGenerator == CosmicWebGenerator.Voronoi)
        {
            var v = VoronoiSettingsOf(p);
            double cell = v.BoxSize / Math.Cbrt(v.Nuclei);
            LastPrecisionLabel = $"Voronoi: {pts.Count:N0} galaxies on the tessellation of {v.Nuclei:N0} nuclei (mean spacing {cell:0.#} Mpc/h), "
                + $"field / walls / filaments / clusters {v.Field:0.##} / {v.Walls:0.##} / {v.Filaments:0.##} / {v.Clusters:0.##}, width {v.Thickness:0.##} Mpc/h" + volumeNote;
            MeasureDimension(p, pts, null, ct);
            return;
        }
        var s = SettingsOf(p);
        LastPrecisionLabel = $"Soneira-Peebles: {pts.Count:N0} points in {pts.ClumpsUsed:N0} clumps"
            + (pts.Capped ? $" (point cap {s.PointCap:N0} reached: {pts.ClumpsRequested - pts.ClumpsUsed:N0} clumps dropped)" : "")
            + $", model D = log {s.Eta} / log {s.Lambda:0.###} = {SoneiraPeebles.AnalyticDimension(s.Eta, s.Lambda):0.###}" + volumeNote;
        MeasureDimension(p, pts, SoneiraPeebles.AnalyticDimension(s.Eta, s.Lambda), ct);   // #2023
    }

    /// <summary>Adds every point's weight into <paramref name="density"/> (fixed point, atomic, order-free).</summary>
    public static void Splat(CosmicWebPoints pts, MathPlane3DCamera cam, double pointSize, double depthFade,
        long[] density, int w, int h, CancellationToken ct = default, long[]? depth = null, int[]? nearest = null)
    {
        double inv = 1.0 / pts.BoxSize;
        double size = double.IsFinite(pointSize) ? Math.Clamp(pointSize, 0.0, MaxPointSize) : 1.0;
        double fade = double.IsFinite(depthFade) ? Math.Clamp(depthFade, 0.0, 1.0) : 0.0;
        // View depth of the box's front and back (the unit cube's circumscribed sphere about the target).
        var (_, _, targetZ) = cam.View(0, 0, 0);
        const double halfDiag = 0.8660254037844386;
        double zFront = targetZ - halfDiag, zSpan = 2 * halfDiag;
        int rad = (int)Math.Ceiling(size);
        double size2 = size * size;
        var xyz = pts.Xyz;
        const int chunk = 1 << 15;
        int chunks = (pts.Count + chunk - 1) / chunk;
        Parallel.For(0, chunks, new ParallelOptions { CancellationToken = ct }, c =>
        {
            int end = Math.Min(pts.Count, (c + 1) * chunk);
            for (int i = c * chunk; i < end; i++)
            {
                double x = xyz[3 * i] * inv - 0.5, y = xyz[3 * i + 1] * inv - 0.5, z = xyz[3 * i + 2] * inv - 0.5;
                if (cam.Project(x, y, z) is not { } q) continue;
                double t = Math.Clamp((1.0 / q.InvZ - zFront) / zSpan, 0.0, 1.0);
                long wt = (long)Math.Round(WeightOne * (1.0 - fade * t));
                if (wt <= 0) continue;
                long wd = wt * (long)Math.Round(DepthOne * t);
                // Ray distance from the eye (positive float bits order like the floats, so an atomic int
                // min keeps the nearest galaxy whatever the order).
                int distBits = 0;
                if (nearest != null)
                {
                    double ex = x - cam.Eye.X, ey = y - cam.Eye.Y, ez = z - cam.Eye.Z;
                    distBits = BitConverter.SingleToInt32Bits((float)Math.Sqrt(ex * ex + ey * ey + ez * ez));
                }
                if (rad == 0 || size < 0.75)
                {
                    int px = (int)Math.Floor(q.X), py = (int)Math.Floor(q.Y);
                    if ((uint)px < (uint)w && (uint)py < (uint)h)
                    {
                        Interlocked.Add(ref density[py * w + px], wt);
                        if (depth != null) Interlocked.Add(ref depth[py * w + px], wd);
                        if (nearest != null) AtomicMin(ref nearest[py * w + px], distBits);
                    }
                    continue;
                }
                int cx = (int)Math.Floor(q.X), cy = (int)Math.Floor(q.Y);
                for (int dy = -rad; dy <= rad; dy++)
                {
                    int py = cy + dy;
                    if ((uint)py >= (uint)h) continue;
                    double ddy = py + 0.5 - q.Y;
                    for (int dx = -rad; dx <= rad; dx++)
                    {
                        int px = cx + dx;
                        if ((uint)px >= (uint)w) continue;
                        double ddx = px + 0.5 - q.X;
                        if (ddx * ddx + ddy * ddy > size2) continue;
                        Interlocked.Add(ref density[py * w + px], wt);
                        if (depth != null) Interlocked.Add(ref depth[py * w + px], wd);
                        if (nearest != null) AtomicMin(ref nearest[py * w + px], distBits);
                    }
                }
            }
        });
    }

    private static void AtomicMin(ref int slot, int value)
    {
        int cur = Volatile.Read(ref slot);
        while (value < cur)
        {
            int seen = Interlocked.CompareExchange(ref slot, value, cur);
            if (seen == cur) return;
            cur = seen;
        }
    }

    private void ToneMap(CosmicWebColour mode, double gamma)
    {
        long max = 0;
        foreach (long v in DensityBuffer) if (v > max) max = v;
        double invLog = max > 0 ? 1.0 / Math.Log(1.0 + (double)max / WeightOne) : 0.0;
        double invGamma = 1.0 / (double.IsFinite(gamma) ? Math.Clamp(gamma, 0.1, 10.0) : 2.2);
        ColorMap.MaxIterations = 256;
        uint empty = ColorMap.InSetColor | 0xFF000000u;
        var d = DensityBuffer;
        var dep = DepthSumBuffer;
        var c = ColorBuffer;
        var map = ColorMap;
        for (int i = 0; i < d.Length; i++)
        {
            long v = d[i];
            if (v <= 0) { c[i] = empty; continue; }
            double a = Math.Log(1.0 + (double)v / WeightOne) * invLog;
            if (mode == CosmicWebColour.Density) { c[i] = (uint)map.Map((float)(a * 256), 0f, 256); continue; }
            double t = Math.Clamp((double)dep[i] / ((double)v * DepthOne), 0.0, 1.0);
            uint packed = (uint)map.Map((float)(t * 256), 0f, 256);
            double bright = Math.Pow(a, invGamma);
            uint r = (packed >> 16) & 0xFFu, g = (packed >> 8) & 0xFFu, b = packed & 0xFFu;
            c[i] = 0xFF000000u
                 | ((uint)Math.Clamp((int)(r * bright + 0.5), 0, 255) << 16)
                 | ((uint)Math.Clamp((int)(g * bright + 0.5), 0, 255) << 8)
                 | (uint)Math.Clamp((int)(b * bright + 0.5), 0, 255);
        }
    }
}
